{
 "app_name": "splitwise",
 "api_name": "show_group_expenses",
 "path": "/group/{group_id}/expenses",
 "method": "GET",
 "description": "Show or search your expenses from a given group based on various criteria.",
 "parameters": [
  {
   "name": "group_id",
   "type": "integer",
   "required": true,
   "description": "The ID of the group to filter expenses.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
